insert into public.books (id, title, subtitle, author, year, pages, lang, genre_id, color, formats, is_free, free_source, free_query, rating, popularity, mood, tags, description, summary, audience) values
  ('clean-code', 'Чистый код', 'Создание, анализ и рефакторинг', 'Роберт Мартин', 2008, 464, 'ru', 'it', 'blue', array['electronic', 'paper'], false, null, null, 4.7, 98, array['think'], array['программирование', 'код', 'рефакторинг', 'тесты', 'качество кода', 'java'], 'Книга о том, как писать код, который легко читать и менять. Автор разбирает имена, функции, комментарии и тесты на живых примерах и показывает, как шаг за шагом превращать запутанный код в понятный.', 'Код читают намного чаще, чем пишут, поэтому главная цель — понятность. Хорошие имена, маленькие функции и честные тесты экономят команде месяцы работы. Плохой код не появляется сразу — он накапливается из мелких «потом поправлю». Мартин предлагает правило бойскаута: оставляй код чуть чище, чем он был до тебя.', array['Для тех, кто уже пишет код и хочет писать его аккуратнее', 'Как давать понятные имена переменным и функциям', 'Почему функции должны быть маленькими и делать одно дело', 'Когда комментарий нужен, а когда он скрывает плохой код', 'Как тесты помогают смело менять код']),
  ('clean-architecture', 'Чистая архитектура', 'Искусство разработки программного обеспечения', 'Роберт Мартин', 2017, 352, 'ru', 'it', 'black', array['paper', 'electronic'], false, null, null, 4.6, 80, array['think'], array['архитектура', 'solid', 'программирование', 'проектирование'], 'Продолжение «Чистого кода», только на уровень выше: как устроить целую систему, чтобы её можно было развивать годами. Мартин объясняет принципы SOLID, границы между компонентами и почему база данных и фреймворк — это детали.', 'Хорошая архитектура откладывает решения, которые пока рано принимать, и делает дешёвыми будущие изменения. Бизнес-правила должны быть в центре и ни от чего не зависеть, а интерфейс, база и фреймворки — подключаться снаружи. Зависимости направлены только внутрь. Так систему можно тестировать и менять по частям.', array['Для разработчиков, которые проектируют модули и сервисы', 'Что такое принципы SOLID на понятных примерах', 'Как делить систему на компоненты и слои', 'Почему фреймворк и база данных — это детали', 'Как архитектура влияет на скорость команды']),
  ('clean-coder', 'Идеальный программист', 'Как стать профессионалом разработки ПО', 'Роберт Мартин', 2011, 224, 'ru', 'it', 'yellow', array['electronic', 'paper'], false, null, null, 4.4, 62, array['inspire', 'light'], array['карьера', 'профессионализм', 'программирование', 'soft skills', 'оценка сроков'], 'Книга не о коде, а о работе программиста: как говорить «нет» нереальным срокам, оценивать задачи, справляться с давлением и расти в профессии. Много историй из опыта автора.', 'Профессионал отвечает за результат, а не просто выполняет задачи. Честное «нет» лучше пустого обещания, а «да» должно означать конкретное обязательство. Тесты, тренировки и планирование времени — часть работы, а не роскошь. Мартин показывает, что спокойствие под давлением держится на дисциплине.', array['Для начинающих и средних разработчиков', 'Как отказывать и договариваться о сроках', 'Как оценивать задачи без самообмана', 'Как держать темп и не выгорать', 'Чему учиться у наставников']),
  ('code-complete', 'Совершенный код', 'Практическое руководство по разработке ПО', 'Стив Макконнелл', 2004, 896, 'ru', 'it', 'orange', array['paper'], false, null, null, 4.7, 75, array['think'], array['программирование', 'конструирование', 'качество кода', 'отладка'], 'Большой справочник по тому, как писать программы: от выбора имён переменных до отладки и оптимизации. Каждое правило подкреплено исследованиями и примерами.', 'Главная работа программиста — управлять сложностью. Чем меньше деталей нужно держать в голове, тем меньше ошибок. Макконнелл разбирает каждый уровень: проектирование, переменные, циклы, условия, тестирование и отладку. Книгу удобно читать кусками и возвращаться к ней.', array['Для тех, кто хочет системно понять ремесло программиста', 'Как проектировать классы и функции', 'Как писать понятные условия и циклы', 'Как искать и исправлять ошибки', 'Когда оптимизировать код, а когда не стоит']),
  ('refactoring', 'Рефакторинг', 'Улучшение существующего кода', 'Мартин Фаулер', 1999, 432, 'ru', 'it', 'green', array['electronic', 'paper'], false, null, null, 4.6, 70, array['think'], array['рефакторинг', 'программирование', 'качество кода', 'тесты'], 'Каталог приёмов, которые делают код лучше, не меняя его поведения. Фаулер показывает, как распознать «код с душком» и маленькими безопасными шагами привести его в порядок.', 'Рефакторинг — это не переписывание с нуля, а серия маленьких шагов, после каждого из которых программа работает. Без тестов рефакторинг опасен, поэтому сначала пишутся тесты. Книга учит замечать проблемные места и подбирать к ним конкретный приём. Это помогает держать проект живым годами.', array['Для тех, кто поддерживает чужой или старый код', 'Как узнать «код с душком»', 'Какими шагами безопасно менять код', 'Зачем нужны тесты перед изменениями', 'Как не бояться трогать работающее']),
  ('pragmatic', 'Программист-прагматик', 'Путь от подмастерья к мастеру', 'Хант, Томас', 1999, 288, 'ru', 'it', 'cream', array['paper'], false, null, null, 4.6, 72, array['inspire', 'think'], array['программирование', 'карьера', 'инструменты', 'dry'], 'Сборник практических советов для программиста: от принципа DRY до работы с инструментами и требованиями. Короткие разделы, которые легко применить на следующий день.', 'Прагматик отвечает за свой код и постоянно учится. Не повторяйся, автоматизируй рутину и делай маленькие проверяемые шаги. Не оставляй «разбитых окон» — мелкий беспорядок быстро растёт. Хороший программист знает свои инструменты и умеет общаться.', array['Для программистов любого уровня', 'Что такое принцип DRY и ортогональность', 'Как выбирать и осваивать инструменты', 'Как защищаться от ошибок заранее', 'Как работать с требованиями']),
  ('grokking', 'Грокаем алгоритмы', 'Иллюстрированное пособие для программистов и любопытствующих', 'Адитья Бхаргава', 2016, 288, 'ru', 'it', 'yellow', array['electronic', 'paper'], false, null, null, 4.8, 90, array['light', 'think'], array['алгоритмы', 'структуры данных', 'программирование', 'python', 'собеседование'], 'Самое понятное введение в алгоритмы: с картинками, без тяжёлой математики. Бинарный поиск, сортировки, рекурсия, графы и динамическое программирование на простых примерах.', 'Алгоритм — это просто способ решить задачу, и у разных способов разная скорость. Бхаргава объясняет «O-большое» на бытовых примерах и рисунках. Шаг за шагом книга доходит до графов, жадных алгоритмов и динамического программирования. После неё легче читать серьёзные учебники и проходить собеседования.', array['Для новичков и тех, кто боится алгоритмов', 'Что такое O-большое и почему это важно', 'Как работают сортировки и бинарный поиск', 'Как искать путь в графе', 'С чего начать подготовку к собеседованию']),
  ('code-petzold', 'Код', 'Тайный язык информатики', 'Чарльз Петцольд', 1999, 448, 'ru', 'it', 'cream', array['paper'], false, null, null, 4.8, 66, array['think', 'inspire'], array['компьютер', 'двоичный код', 'электроника', 'история', 'процессор'], 'Как из фонарика, реле и азбуки Морзе получается компьютер. Петцольд шаг за шагом собирает вычислительную машину прямо на страницах книги — понятно даже без технического образования.', 'Любой компьютер — это огромное количество простых переключателей. Книга начинает с сигналов фонариком и азбуки Морзе, переходит к двоичной системе и логическим элементам. Из них собираются сумматор, память и процессор. В конце понятно, что происходит внутри машины, когда запускается программа.', array['Для всех, кому интересно, как устроен компьютер', 'Что такое двоичный код', 'Как работают логические элементы', 'Как устроены память и процессор', 'Откуда взялись операционные системы']),
  ('lua', 'Программирование на языке Lua', null, 'Роберту Иерузалимски', 2016, 382, 'ru', 'it', 'navy', array['paper', 'electronic'], false, null, null, 4.5, 50, array['think'], array['lua', 'roblox', 'геймдев', 'скрипты', 'программирование', 'luau'], 'Книга от создателя языка Lua — того самого, на котором (в виде Luau) пишут скрипты в Roblox. Таблицы, функции, корутины и метатаблицы объяснены из первых рук.', 'Lua — маленький и быстрый язык, который встраивают в игры и программы. Почти всё в нём строится на таблицах: массивы, словари, объекты и модули. Автор показывает, как работают замыкания, корутины и метатаблицы. Для Roblox-разработчика это прочный фундамент под Luau.', array['Для Roblox-разработчиков и тех, кто пишет игровые скрипты', 'Как устроены таблицы и метатаблицы', 'Что такое замыкания и корутины', 'Как писать модули', 'Чем Lua отличается от других языков']),
  ('game-design', 'Геймдизайн', 'Как создать игру, в которую будут играть все', 'Джесси Шелл', 2008, 640, 'ru', 'it', 'green', array['paper', 'electronic'], false, null, null, 4.6, 58, array['inspire', 'think'], array['геймдев', 'геймдизайн', 'игры', 'roblox'], 'Книга о том, как придумывать игры, которые цепляют. Шелл предлагает больше сотни «линз» — вопросов, через которые полезно посмотреть на свою игру.', 'Игра — это опыт, который переживает игрок, а не набор механик. Шелл учит смотреть на проект через «линзы»: цель, баланс, интерес, история, команда. Хороший дизайн рождается из прототипов и тестов на живых людях. Книга подходит и для настолок, и для видеоигр.', array['Для тех, кто делает свои игры, в том числе в Roblox', 'Как придумать идею и проверить её', 'Что такое баланс и почему игра скучает', 'Как связать механику и историю', 'Как тестировать на игроках']),
  ('blood-sweat-pixels', 'Кровь, пот и пиксели', 'Обратная сторона индустрии видеоигр', 'Джейсон Шрейер', 2017, 352, 'ru', 'it', 'maroon', array['electronic', 'paper'], false, null, null, 4.5, 64, array['light', 'inspire'], array['геймдев', 'игры', 'истории', 'индустрия'], 'Десять историй о том, как на самом деле делают игры: от инди-проектов до больших студий. Кранчи, переносы сроков и чудеса в последний момент.', 'Почти каждая известная игра была на грани провала. Шрейер рассказывает, как создавались Stardew Valley, Diablo III, The Witcher 3 и другие проекты. Видно, сколько решений принимается в спешке и почему сроки почти всегда срываются. Читается как сборник детективов о работе.', array['Для тех, кто мечтает работать в геймдеве', 'Как устроены игровые студии изнутри', 'Почему игры переносят', 'Как инди-разработчики выживают в одиночку', 'Что такое кранч и чем он опасен']),
  ('master-margarita', 'Мастер и Маргарита', null, 'Михаил Булгаков', 1967, 480, 'ru', 'fantasy', 'maroon', array['electronic', 'paper'], true, 'wikisource', 'Мастер и Маргарита Булгаков', 4.8, 99, array['think'], array['роман', 'мистика', 'москва', 'классика', 'русская литература'], 'В Москву 1930-х приезжает таинственный профессор Воланд со свитой — и город начинает сходить с ума. Параллельно идёт роман о Понтии Пилате и любовь Мастера и Маргариты.', 'Воланд и его свита устраивают в Москве череду чудес и скандалов, разоблачая жадность и трусость горожан. Мастер написал роман о Пилате и сломался под травлей критиков. Маргарита ради него соглашается стать королевой бала у сатаны. Книга о трусости, милосердии и о том, что рукописи не горят.', array['Для тех, кто любит мистику и сатиру', 'Почему трусость — самый страшный порок', 'Как переплетаются Москва и Ершалаим', 'Что такое настоящая любовь и верность', 'Как Булгаков смеётся над бюрократией']),
  ('picnic', 'Пикник на обочине', null, 'Стругацкие', 1972, 224, 'ru', 'fantasy', 'moss', array['electronic', 'paper'], false, null, null, 4.7, 88, array['think'], array['фантастика', 'зона', 'сталкер', 'стругацкие'], 'После визита инопланетян на Земле остались Зоны — места, полные опасных и ценных артефактов. Сталкер Рэдрик Шухарт раз за разом ходит туда, рискуя жизнью.', 'Пришельцы побывали на Земле и улетели, даже не заметив людей, — как туристы, оставившие мусор после пикника. В Зоне лежат вещи, которые могут изменить мир, но никто не понимает, как они работают. Рэдрик ходит туда ради денег и семьи, и каждый поход меняет его. Финал — о том, чего человек на самом деле хочет для всех.', array['Для любителей умной фантастики', 'Откуда пошла идея «сталкера» и Зоны', 'Что люди делают с непонятным', 'Цена риска ради близких', 'Почему финал цитируют до сих пор']),
  ('atomic-habits', 'Атомные привычки', 'Как приобрести хорошие привычки и избавиться от плохих', 'Джеймс Клир', 2018, 304, 'ru', 'self', 'cream', array['electronic', 'paper'], false, null, null, 4.6, 95, array['inspire', 'light'], array['привычки', 'продуктивность', 'мотивация', 'психология'], 'Маленькие изменения, которые дают огромный результат. Клир объясняет, как устроены привычки, и даёт четыре простых правила, чтобы закрепить хорошие и убрать плохие.', 'Улучшение на один процент в день за год превращается в огромную разницу. Привычка — это цикл: сигнал, желание, действие, награда. Чтобы закрепить хорошую привычку, её делают очевидной, привлекательной, простой и приятной; плохую — наоборот. Главное — менять не цели, а то, кем ты себя считаешь.', array['Для тех, кто хочет менять жизнь маленькими шагами', 'Как устроена любая привычка', 'Почему цели работают хуже систем', 'Как «привязать» новую привычку к старой', 'Как избавиться от плохих привычек']),
  ('abai-path', 'Путь Абая', null, 'Мухтар Ауэзов', 1942, 1200, 'ru', 'classic', 'navy', array['paper'], false, null, null, 4.8, 84, array['think', 'inspire'], array['казахская литература', 'эпопея', 'абай', 'степь', 'история', 'казахстан'], 'Роман-эпопея о жизни поэта Абая Кунанбаева и казахской степи XIX века. Взросление, конфликт с отцом, поиск знаний и правды.', 'Абай растёт в семье властного Кунанбая, но рано понимает, что сила — не главное. Он тянется к знаниям, поэзии и справедливости, а это ссорит его с родом. Ауэзов показывает всю жизнь степи: кочёвки, споры, обычаи и перемены. Это книга о человеке, который опередил своё время.', array['Для тех, кто хочет узнать историю и культуру Казахстана', 'Как жила казахская степь в XIX веке', 'Каким был путь Абая к поэзии', 'Конфликт поколений и традиций', 'Почему эпопею называют энциклопедией жизни народа']),
  ('abai-zholy', 'Абай жолы', null, 'Мұхтар Әуезов', 1942, 1200, 'kk', 'classic', 'moss', array['paper'], false, null, null, 4.8, 60, array['think'], array['қазақ әдебиеті', 'абай', 'роман-эпопея', 'путь абая', 'казахстан'], 'Мұхтар Әуезовтің Абай Құнанбайұлының өмірі туралы роман-эпопеясы — казахский оригинал «Пути Абая».', 'Ақын Абайдың балалық шағынан бастап өмірінің соңына дейінгі жолы. Эпопея XIX ғасырдағы қазақ даласының тұрмысын, салт-дәстүрін және өзгерістерін көрсетеді.', array['Қазақ тілінде оқығысы келетіндерге', 'Абайдың өмірі мен шығармашылығы', 'XIX ғасырдағы қазақ даласы']),
  ('baskerville', 'Собака Баскервилей', null, 'Артур Конан Дойл', 1902, 256, 'ru', 'detective', 'black', array['electronic', 'paper'], true, 'gutenberg', 'The Hound of the Baskervilles', 4.7, 86, array['light'], array['шерлок холмс', 'детектив', 'англия', 'классика'], 'Над родом Баскервилей висит проклятие — огромный пёс с болот. Шерлок Холмс и доктор Ватсон должны защитить наследника и выяснить, кто стоит за легендой.', 'Сэр Чарльз Баскервиль умирает при странных обстоятельствах, а рядом находят следы огромной собаки. Наследник Генри приезжает в поместье, и Холмс отправляет с ним Ватсона. На туманных болотах у каждого соседа есть секрет. Разгадка показывает, что за мистикой почти всегда стоит человек.', array['Для любителей классического детектива', 'Как Холмс отделяет факты от легенд', 'Почему Ватсон тоже хороший сыщик', 'Атмосфера английских болот', 'С чего начать знакомство с Холмсом']),
  ('orient-express', 'Убийство в «Восточном экспрессе»', null, 'Агата Кристи', 1934, 256, 'ru', 'detective', 'navy', array['electronic', 'paper'], false, null, null, 4.7, 82, array['light'], array['эркюль пуаро', 'детектив', 'поезд', 'классика'], 'Поезд застрял в снегах, в купе найден убитый пассажир, и у каждого из двенадцати попутчиков есть алиби. Эркюль Пуаро начинает расследование.', 'Ночью в заснеженном поезде убит богатый американец. Пуаро по очереди допрашивает пассажиров, и все показания странно сходятся. Постепенно выясняется, что жертва скрывала страшное прошлое. Финал ставит вопрос: всегда ли закон и справедливость — одно и то же.', array['Для тех, кто любит загадки «в замкнутом пространстве»', 'Как Пуаро работает «серыми клеточками»', 'Один из самых известных финалов в детективах', 'Можно ли оправдать месть']),
  ('little-prince', 'Маленький принц', null, 'Антуан де Сент-Экзюпери', 1943, 96, 'ru', 'kids', 'yellow', array['electronic', 'paper'], false, null, null, 4.8, 94, array['light', 'think'], array['сказка', 'притча', 'для детей', 'дружба'], 'Лётчик терпит аварию в пустыне и встречает мальчика с маленькой планеты. Тот рассказывает о своей розе, путешествиях и о том, что взрослые часто не видят главного.', 'Маленький принц покидает свою планету и розу и путешествует по странным мирам взрослых. На Земле он встречает Лиса, который учит его дружбе и ответственности. «Зорко одно лишь сердце» — главная мысль сказки. Это книга, которую по-разному читают в восемь и в тридцать лет.', array['Для детей и взрослых', 'Почему мы в ответе за тех, кого приручили', 'Что взрослые упускают в жизни', 'О дружбе и потере', 'Короткая книга на один вечер']),
  ('harry-potter', 'Гарри Поттер и философский камень', null, 'Джоан Роулинг', 1997, 432, 'ru', 'kids', 'maroon', array['electronic', 'paper'], false, null, null, 4.8, 92, array['light', 'inspire'], array['волшебство', 'хогвартс', 'фэнтези', 'для детей', 'приключения'], 'В одиннадцать лет Гарри узнаёт, что он волшебник, и попадает в школу Хогвартс. Новые друзья, магия и первая встреча с тайной, которая связана с его прошлым.', 'Сирота Гарри живёт в чулане у злых родственников, пока не получает письмо из Хогвартса. В школе он находит друзей — Рона и Гермиону — и узнаёт, почему его знает весь волшебный мир. Вместе они раскрывают тайну философского камня. Книга о смелости, дружбе и выборе, который важнее способностей.', array['Для детей от 9 лет и взрослых', 'С чего начинается большая сага', 'О дружбе и смелости', 'Как устроен мир волшебников']),
  ('deniska', 'Денискины рассказы', null, 'Виктор Драгунский', 1959, 192, 'ru', 'kids', 'orange', array['electronic', 'paper'], false, null, null, 4.8, 70, array['light'], array['рассказы', 'для детей', 'юмор', 'школа'], 'Смешные и добрые истории о школьнике Дениске Кораблёве и его друге Мишке. Каждый рассказ — на несколько минут, идеально для чтения вслух.', 'Дениска живёт в Москве, ходит в школу и постоянно попадает в забавные ситуации. За смешными историями прячутся серьёзные вещи: честность, дружба, умение признавать ошибки. Рассказы короткие, их удобно читать перед сном. Многие фразы из книги давно стали крылатыми.', array['Для детей 6–10 лет и чтения вслух', 'Смешные истории о школе и дружбе', 'О честности и ошибках', 'Короткие рассказы на вечер']),
  ('old-man-sea', 'Старик и море', null, 'Эрнест Хемингуэй', 1952, 128, 'ru', 'classic', 'blue', array['electronic', 'paper'], false, null, null, 4.5, 74, array['think', 'inspire'], array['повесть', 'море', 'классика', 'нобелевская премия'], 'Старый кубинский рыбак 84 дня не может ничего поймать. На 85-й он уходит далеко в море и вступает в многодневную схватку с огромной рыбой.', 'Сантьяго считают неудачником, но он не сдаётся и уплывает дальше всех. Огромная рыба тянет его лодку несколько дней, и старик уважает её как равного соперника. Победа даётся дорогой ценой, а по пути домой её отнимают акулы. Повесть о том, что человека можно уничтожить, но нельзя победить.', array['Для тех, кто хочет прочитать классику за вечер', 'О стойкости и достоинстве', 'Почему книга принесла автору Нобелевскую премию', 'Простой язык, глубокий смысл']),
  ('overcoat', 'Шинель', null, 'Николай Гоголь', 1842, 64, 'ru', 'classic', 'moss', array['electronic', 'paper'], true, 'wikisource', 'Шинель Гоголь', 4.4, 68, array['think'], array['повесть', 'петербург', 'маленький человек', 'классика', 'русская литература'], 'Тихий чиновник Акакий Акакиевич копит на новую шинель — и это становится главным событием его жизни. Повесть, из которой, как говорят, «вышла вся русская литература».', 'Акакий Акакиевич всю жизнь переписывает бумаги и ничего больше не хочет. Старая шинель разваливается, и он долго копит на новую. Радость длится один вечер: шинель отнимают грабители, а «значительное лицо» отказывает в помощи. После смерти чиновника по Петербургу начинает ходить призрак, срывающий шинели.', array['Для тех, кто хочет понять русскую классику', 'Кто такой «маленький человек»', 'Как Гоголь сочетает смех и жалость', 'Читается за час']),
  ('metamorphosis', 'Превращение', null, 'Франц Кафка', 1915, 96, 'ru', 'classic', 'orange', array['electronic', 'paper'], true, 'gutenberg', 'Metamorphosis Kafka', 4.3, 72, array['think'], array['повесть', 'абсурд', 'классика', 'семья'], 'Коммивояжёр Грегор Замза однажды утром просыпается огромным насекомым. Главный вопрос — не как это случилось, а как к нему теперь относится семья.', 'Грегор кормил всю семью, а после превращения сразу становится обузой. Родные сначала жалеют его, потом стыдятся и в конце концов мечтают избавиться. Кафка спокойным тоном описывает абсурдную ситуацию, и от этого становится только страшнее. Повесть о том, как быстро человека перестают видеть за его пользой.', array['Для тех, кто хочет познакомиться с Кафкой', 'Что такое «кафкианский» абсурд', 'О семье, долге и одиночестве', 'Короткая книга, которая долго не отпускает']),
  ('heart-of-dog', 'Собачье сердце', null, 'Михаил Булгаков', 1925, 160, 'ru', 'fantasy', 'black', array['electronic', 'paper'], true, 'wikisource', 'Собачье сердце Булгаков', 4.8, 85, array['light', 'think'], array['повесть', 'сатира', 'эксперимент', 'классика', 'русская литература'], 'Профессор Преображенский пересаживает бездомному псу Шарику человеческий гипофиз. Пёс превращается в человека — и проблемы только начинаются.', 'Профессор хотел найти способ омоложения, а получил Полиграфа Полиграфовича Шарикова. Новый «человек» быстро учится хамить, писать доносы и требовать жилплощадь. Преображенский понимает, что природу нельзя торопить. Острая и смешная сатира на попытки переделать людей сверху.', array['Для любителей сатиры', 'Почему эксперимент над природой опасен', 'Как Булгаков высмеивает эпоху', 'Читается за один вечер']),
  ('algernon', 'Цветы для Элджернона', null, 'Дэниел Киз', 1959, 320, 'ru', 'fantasy', 'cream', array['electronic', 'paper'], false, null, null, 4.8, 89, array['think'], array['фантастика', 'эксперимент', 'интеллект', 'дневник'], 'Чарли Гордон с низким интеллектом соглашается на экспериментальную операцию. Мы читаем его отчёты — и видим, как меняется не только ум, но и вся жизнь.', 'До Чарли операцию сделали мышонку Элджернону, и тот стал гением. Отчёты Чарли сначала полны ошибок, потом становятся всё сложнее и умнее. Вместе с умом приходит одиночество: он начинает понимать, как к нему относились раньше. Книга о том, что ум без доброты и тепла не делает человека счастливым.', array['Для тех, кто хочет книгу, которая трогает', 'Что значит быть человеком', 'Ум и чувства — что важнее', 'Необычная форма — дневник героя']),
  ('white-fang', 'Белый Клык', null, 'Джек Лондон', 1906, 288, 'ru', 'classic', 'maroon', array['electronic', 'paper'], true, 'gutenberg', 'White Fang London', 4.7, 76, array['inspire', 'light'], array['приключения', 'север', 'волк', 'классика', 'для детей'], 'История волка-полукровки, родившегося в дикой северной природе. Он проходит через жестокость людей, но встречает того, кто учит его доверию.', 'Белый Клык рождается в лесу и с детства учится выживать. Люди сначала делают из него бойцового пса и превращают в злобного зверя. Всё меняется, когда его выкупает Уидон Скотт — человек, который отвечает добром на ярость. Книга о том, как любовь меняет даже самое дикое сердце.', array['Для подростков и взрослых', 'Жизнь дикой природы Севера', 'Как жестокость и доброта меняют характер', 'Классика приключенческой литературы']),
  ('dune', 'Дюна', null, 'Фрэнк Герберт', 1965, 704, 'ru', 'fantasy', 'orange', array['electronic', 'paper'], false, null, null, 4.7, 87, array['think', 'inspire'], array['фантастика', 'космос', 'пустыня', 'политика', 'эпопея'], 'Пустынная планета Арракис — единственный источник самого ценного вещества во вселенной. Юный Пол Атрейдес оказывается в центре борьбы за власть.', 'Дом Атрейдесов получает в управление Арракис, но это ловушка их врагов. После предательства Пол и его мать бегут в пустыню к свободным людям — фрименам. Пол учится жить среди песков и постепенно становится их лидером. Роман о власти, экологии и опасности веры в мессию.', array['Для любителей масштабной фантастики', 'Как устроен мир Дюны', 'Политика, религия и экология в одном сюжете', 'Почему книгу считают классикой жанра']),
  ('kahneman', 'Думай медленно… решай быстро', null, 'Даниэль Канеман', 2011, 656, 'ru', 'self', 'green', array['electronic', 'paper'], false, null, null, 4.5, 78, array['think'], array['психология', 'мышление', 'решения', 'экономика'], 'Нобелевский лауреат объясняет, как работает наше мышление и почему мы так часто ошибаемся. Две системы: быстрая интуиция и медленный расчёт.', 'В голове работают две системы: Система 1 думает быстро и интуитивно, Система 2 — медленно и с усилием. Большую часть решений принимает быстрая система, и она легко ошибается. Канеман показывает десятки таких ошибок — от якорения до боязни потерь. Зная их, можно принимать решения спокойнее и точнее.', array['Для тех, кто хочет лучше понимать себя', 'Как работают интуиция и логика', 'Какие ошибки мышления делают все', 'Почему мы боимся потерь сильнее, чем радуемся выигрышу']),
  ('sapiens', 'Sapiens. Краткая история человечества', null, 'Юваль Ной Харари', 2011, 512, 'ru', 'self', 'blue', array['electronic', 'paper'], false, null, null, 4.6, 83, array['think', 'inspire'], array['история', 'наука', 'человечество', 'научпоп'], 'Как ничем не примечательный вид обезьян стал хозяином планеты. Харари рассказывает историю человечества через четыре революции.', 'Люди победили благодаря умению верить в общие истории — богов, деньги, государства. Аграрная революция дала больше еды, но не сделала людей счастливее. Деньги, империи и религии объединили человечество, а научная революция ускорила всё. В конце автор спрашивает, куда мы движемся дальше.', array['Для всех, кто любит большие идеи', 'Почему именно Homo sapiens победил', 'Как появились деньги и государства', 'Что такое «общие мифы»']);
